#!/usr/bin/env python3
from __future__ import annotations
import base64,re,shutil,subprocess,sys,time
from pathlib import Path

PATCH_ID='MEMEFLOW_DISCOVERY_ROUTER_V1_1'
STAMP=time.strftime('%Y%m%d-%H%M%S')
PAYLOADS={'discovery-source.mjs': '', 'dex-discovery-feed.mjs': '', 'system-source.html': ''}

def log(x): print('[DISCOVERY-V1.1] '+str(x),flush=True)

def find_root():
    candidates=[Path.cwd(),Path.cwd()/'memeflow-app',Path.home()/'workspace',Path.home()/'workspace'/'memeflow-app',Path('/home/runner/workspace'),Path('/home/runner/workspace/memeflow-app'),Path('/workspace'),Path('/workspace/memeflow-app')]
    for r in candidates:
        try:r=r.resolve()
        except:continue
        if (r/'app-server.mjs').is_file() and (r/'src/settings.mjs').is_file(): return r
    for base in [Path('/home/runner/workspace'),Path.cwd()]:
        if not base.exists(): continue
        for p in base.glob('**/app-server.mjs'):
            if (p.parent/'src/settings.mjs').is_file(): return p.parent.resolve()
    raise RuntimeError('MEMEFLOW project root not found')

ROOT=find_root(); SRC=ROOT/'src'; APP=ROOT/'app-server.mjs'; SETTINGS=SRC/'settings.mjs'; EVALUATE=SRC/'evaluate.mjs'
BACK=ROOT/f'.discovery-router-v1-1-backup-{STAMP}'; BACK.mkdir(parents=True,exist_ok=True)
changed=[]

def rel(p): return p.resolve().relative_to(ROOT.resolve())
def backup(p):
    if p in changed:return
    if p.exists():
        d=BACK/rel(p);d.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,d)
    changed.append(p)
def write(p,text):
    backup(p);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8');log('patched '+str(rel(p)))
def write_payload(name,target): write(target,base64.b64decode(PAYLOADS[name]).decode('utf-8'))
def rollback(err):
    log('ERROR: '+str(err))
    for p in reversed(changed):
        b=BACK/rel(p)
        try:
            if b.exists(): shutil.copy2(b,p);log('restored '+str(rel(p)))
            elif p.exists(): p.unlink();log('removed new '+str(rel(p)))
        except Exception as e: log('rollback warning '+str(e))
    log('ROLLBACK COMPLETE');sys.exit(1)

def replace_once(text,old,new,label):
    n=text.count(old)
    if n!=1: raise RuntimeError(f'{label}: expected exactly 1 anchor, found {n}')
    return text.replace(old,new,1)

def regex_once(text,pattern,repl,label,flags=0):
    out,n=re.subn(pattern,repl,text,count=1,flags=flags)
    if n!=1: raise RuntimeError(f'{label}: expected exactly 1 regex anchor, found {n}')
    return out

def patch_settings(text):
    text=replace_once(text,"const PLATFORMS=['pump'];","const PLATFORMS=['pump','dex'];",'settings platform list')
    text=replace_once(text,"launchPlatforms:['pump'],","launchPlatforms:['pump','dex'],",'settings defaults')
    old=""" // Current discovery backend is Pump.fun only. Do not expose a pretend multi-launchpad filter.\n o.launchPlatforms=['pump'];"""
    new=""" // Discovery source is server-global (PUMP / DEX / HYBRID).\n // Keep both normalized here so the selected engine source is not discarded downstream.\n o.launchPlatforms=['pump','dex'];"""
    text=replace_once(text,old,new,'settings normalize source')
    oldv="if(!Array.isArray(s.launchPlatforms)||s.launchPlatforms.length!==1||s.launchPlatforms[0]!=='pump')errors.push('Current discovery supports Pump.fun only.');"
    newv="if(!Array.isArray(s.launchPlatforms)||s.launchPlatforms.some(x=>!PLATFORMS.includes(String(x).toLowerCase())))errors.push('Invalid launch platform. Supported discovery platforms are pump and dex.');"
    text=replace_once(text,oldv,newv,'settings validation')
    return text

def patch_evaluate(text):
    # Robust wrapper: do not depend on the internal formatting of the developer gate.
    if 'MEMEFLOW_DEX_CREATOR_NA_WRAPPER_V1_1' in text:
        return text

    matches=list(re.finditer(r"export\s+function\s+evaluate\s*\(", text))
    if len(matches)!=1:
        raise RuntimeError(
            f'DEX evaluator wrapper: expected one exported evaluate() function, found {len(matches)}'
        )

    text=re.sub(
        r"export\s+function\s+evaluate\s*\(",
        "function __mfEvaluateBaseV11(",
        text,
        count=1
    )

    wrapper=r"""
// MEMEFLOW_DEX_CREATOR_NA_WRAPPER_V1_1
// A confirmed DEX pool does not prove the original creator wallet.
// Unknown creator data is N/A, not WAITING and not fake 0%.
export function evaluate(token, s = {}) {
  const dexCreatorUnavailable =
    String(token?.launchPlatform || '').toLowerCase() === 'dex' &&
    token?.creator == null &&
    token?.developerPct == null;

  if (!dexCreatorUnavailable) {
    return __mfEvaluateBaseV11(token, s);
  }

  const result = __mfEvaluateBaseV11(
    token,
    {...s, maxDeveloperPct:null}
  );

  const gates = result?.settingsEvaluation?.gates;
  if (Array.isArray(gates)) {
    gates.push({
      name:'Developer concentration',
      status:'N/A',
      pass:true,
      reason:'creator identity unavailable from confirmed DEX pool'
    });
  }

  return result;
}
"""
    return text.rstrip()+"\n"+wrapper+"\n"

def patch_app(text):
    # Imports: tolerate whitespace/comment changes.
    imp_re=r"import\s*\{\s*startPumpLiveTradeFeed\s*\}\s*from\s*['\"]\.\/src\/pump-live-trade-feed\.mjs['\"]\s*;[^\n]*"
    matches=list(re.finditer(imp_re,text))
    if len(matches)!=1:
        raise RuntimeError(f'app imports: expected Pump live-feed import once, found {len(matches)}')
    m=matches[0]
    old=m.group(0)
    new=(
      old+
      "\nimport { DiscoverySourceController } from './src/discovery-source.mjs'; // "+PATCH_ID+
      "\nimport { startDexDiscoveryFeed } from './src/dex-discovery-feed.mjs'; // "+PATCH_ID
    )
    text=text[:m.start()]+new+text[m.end():]

    root_re=r"(const\s+root=path\.dirname\(fileURLToPath\(import\.meta\.url\)\),dataDir=path\.resolve\(root,process\.env\.DATA_DIR\|\|'data'\),store=new\s+JsonStore\(dataDir\);)"
    text=regex_once(
      text,
      root_re,
      r"\1\nconst __discoverySource=new DiscoverySourceController({dataDir,defaultMode:process.env.DISCOVERY_SOURCE_MODE||'dex'});\nconst __discoverySourceAllows=source=>__discoverySource.allows(source);",
      'source controller init'
    )

    if "discoveryPlatforms:['pump']" in text:
        text=text.replace(
          "discoveryPlatforms:['pump']",
          "discoveryPlatforms:['pump','dex'],discoverySourceMode:__discoverySource.mode",
          1
        )

    route_re=r"(?m)^(\s*)if\(url\.pathname==='/api/settings'&&req\.method==='GET'\)\{"
    route_matches=list(re.finditer(route_re,text))
    if len(route_matches)!=1:
        raise RuntimeError(
          f'discovery source API anchor: expected /api/settings GET once, found {len(route_matches)}'
        )
    rm=route_matches[0]
    indent=rm.group(1)
    routes=(
      indent+"if(url.pathname==='/api/discovery-source'&&req.method==='GET')return json(res,200,__discoverySourceStatus());\n"+
      indent+"if(url.pathname==='/api/discovery-source'&&req.method==='POST'){\n"+
      indent+"  if(!u.isOwner)return json(res,403,{error:'OWNER_REQUIRED',message:'Only the owner can switch the global discovery source.'});\n"+
      indent+"  const b=await body(req);\n"+
      indent+"  try{__discoverySource.set(b?.mode);__applyDiscoverySourceMode();return json(res,200,__discoverySourceStatus())}\n"+
      indent+"  catch(e){return json(res,400,{error:e.code||'INVALID_DISCOVERY_SOURCE',message:e.message})}\n"+
      indent+"}\n"
    )
    text=text[:rm.start()]+routes+text[rm.start():]

    pattern=re.compile(
      r"// MEMEFLOW_V12_21_LIVE_TRADE_STREAM_HOLDER_FEED\n"
      r"const __pumpLiveTradeFeed=startPumpLiveTradeFeed\(\{(?P<body>.*?)\n\}\);",
      re.S
    )
    m=pattern.search(text)
    if not m:
        raise RuntimeError('Pump live feed block anchor not found')
    body=m.group('body')

    manager=f"""// MEMEFLOW_V12_21_LIVE_TRADE_STREAM_HOLDER_FEED
// {PATCH_ID}: discovery feeds are owned by the source router.
const __pumpLiveTradeFeedOpts={{
{body}
}};
let __pumpLiveTradeFeed=null;
let __dexDiscoveryFeed=null;

function __queueDexHolderSnapshot(mint){{
  try{{
    const admission=holderAdmissionForActiveUsers(mint);
    if(admission?.allow!==false){{
      holderQueue.enqueue(mint);
      return true;
    }}
  }}catch(e){{
    console.error('[DEX DISCOVERY] holder queue',mint,e?.message||e);
  }}
  return false;
}}

async function __applyDexDiscovery(info){{
  const mint=info?.mint;
  if(!mint)return;

  const existing=store.state?.tokens?.[mint]||null;
  const identity={{...(info.identity||{{}})}};

  if(existing){{
    store.setToken(mint,{{
      ...identity,
      creator:existing.creator||identity.creator||null,
      creatorStatus:existing.creator?'known':identity.creatorStatus,
      discoveredAt:existing.discoveredAt||identity.discoveredAt,
      launchPlatform:'dex',
      protocol:identity.protocol||existing.protocol||'dex',
      source:identity.source||existing.source||'DEX pool stream',
      dexListedAt:Date.now()
    }});
  }}else{{
    store.addToken({{
      ...identity,
      launchPlatform:'dex',
      dexListedAt:Date.now()
    }});
  }}

  const current=store.state?.tokens?.[mint]||{{}};
  const updated=store.setToken(mint,{{
    ...(info.market||{{}}),
    dataQuality:Math.max(Number(current.dataQuality)||0,0.78),
    dexConfirmed:true,
    dexConfirmedAt:Date.now()
  }});

  // DEX path intentionally skips Pump bonding-curve enrichment and Pump price timers.
  // Only the shared holder queue is requested.
  __queueDexHolderSnapshot(mint);

  try{{await evaluateAll(updated)}}catch(e){{
    console.error('[DEX DISCOVERY] evaluate',mint,e?.message||e);
  }}
  try{{publish(mint)}}catch{{}}
}}

async function __applyDexMarket(mint,patch){{
  const current=store.state?.tokens?.[mint];
  if(!current)return;

  const updated=store.setToken(mint,{{
    ...(patch||{{}}),
    dataQuality:Math.max(
      Number(current.dataQuality)||0,
      current.holderFresh===true?0.94:0.78
    ),
    dexConfirmed:true
  }});

  try{{await evaluateAll(updated)}}catch{{}}
  try{{publish(mint)}}catch{{}}
}}

function __startPumpLiveFeed(){{
  if(!__pumpLiveTradeFeed)
    __pumpLiveTradeFeed=startPumpLiveTradeFeed(__pumpLiveTradeFeedOpts);
}}
function __stopPumpLiveFeed(){{
  if(__pumpLiveTradeFeed){{
    try{{__pumpLiveTradeFeed.stop?.()}}catch{{}}
    __pumpLiveTradeFeed=null;
  }}
}}
function __startDexFeed(){{
  if(!__dexDiscoveryFeed)
    __dexDiscoveryFeed=startDexDiscoveryFeed({{
      rpc,wsUrls,
      onDiscover:__applyDexDiscovery,
      onMarket:__applyDexMarket
    }});
}}
function __stopDexFeed(){{
  if(__dexDiscoveryFeed){{
    try{{__dexDiscoveryFeed.stop?.()}}catch{{}}
    __dexDiscoveryFeed=null;
  }}
}}
function __stopPumpCreateDiscovery(){{
  clearTimeout(wsTimer);
  wsTimer=null;
  try{{if(ws)ws.onclose=null}}catch{{}}
  try{{ws?.close?.()}}catch{{}}
  ws=null;
  discovery.connected=false;
  discovery.error=null;
}}
function __applyDiscoverySourceMode(){{
  if(__discoverySourceAllows('pump')){{
    __startPumpLiveFeed();
    if(!ws)startDiscovery();
  }}else{{
    __stopPumpLiveFeed();
    __stopPumpCreateDiscovery();
  }}

  if(__discoverySourceAllows('dex'))__startDexFeed();
  else __stopDexFeed();

  console.log('[DISCOVERY SOURCE]',__discoverySource.mode);
  return __discoverySource.mode;
}}
function __discoverySourceStatus(){{
  const pumpTrade=__pumpLiveTradeFeed?.metrics?.()||null;
  const dex=__dexDiscoveryFeed?.metrics?.()||null;

  return {{
    source:__discoverySource.snapshot(),
    pump:{{
      connected:Boolean(discovery.connected||pumpTrade?.connected),
      createConnected:Boolean(discovery.connected),
      trade:pumpTrade
    }},
    dex
  }};
}}"""

    text=text[:m.start()]+manager+text[m.end():]

    startup_re=r"(\n\s*)startDiscovery\(\);(\s*\n\s*startDecisionRecovery\()"
    text=regex_once(
      text,
      startup_re,
      r"\1__applyDiscoverySourceMode();\2",
      'server source startup'
    )

    if "liveTradeFeed:__pumpLiveTradeFeed?.metrics?.()||null," in text:
        text=text.replace(
          "liveTradeFeed:__pumpLiveTradeFeed?.metrics?.()||null,",
          "liveTradeFeed:__pumpLiveTradeFeed?.metrics?.()||null,dexDiscovery:__dexDiscoveryFeed?.metrics?.()||null,discoverySource:__discoverySource.snapshot(),",
          1
        )
    return text


try:
    log('root: '+str(ROOT))
    app=APP.read_text(encoding='utf-8');settings=SETTINGS.read_text(encoding='utf-8');evaluate=EVALUATE.read_text(encoding='utf-8')
    if PATCH_ID in app:
        log('patch already installed');sys.exit(0)

    # Preflight all transformations in memory before touching project files.
    new_settings=patch_settings(settings)
    new_evaluate=patch_evaluate(evaluate)
    new_app=patch_app(app)

    write_payload('discovery-source.mjs',SRC/'discovery-source.mjs')
    write_payload('dex-discovery-feed.mjs',SRC/'dex-discovery-feed.mjs')
    write_payload('system-source.html',ROOT/'system-source.html')
    write(SETTINGS,new_settings);write(EVALUATE,new_evaluate);write(APP,new_app)

    for f in [APP,SETTINGS,EVALUATE,SRC/'discovery-source.mjs',SRC/'dex-discovery-feed.mjs']:
        r=subprocess.run(['node','--check',str(f)],cwd=ROOT,capture_output=True,text=True)
        if r.returncode: raise RuntimeError('node --check failed for '+str(rel(f))+':\n'+(r.stderr or r.stdout))
        log('syntax OK '+str(rel(f)))

    # Static invariants: Pump path remains in the code, DEX path is additive and reversible.
    a=APP.read_text(encoding='utf-8');s=SETTINGS.read_text(encoding='utf-8');e=EVALUATE.read_text(encoding='utf-8');d=(SRC/'dex-discovery-feed.mjs').read_text(encoding='utf-8')
    required=[PATCH_ID,"__discoverySourceAllows('pump')","startDexDiscoveryFeed","/api/discovery-source","__applyDiscoverySourceMode"]
    for token in required:
        if token not in a: raise RuntimeError('validation missing in app-server.mjs: '+token)
    if "const PUMP='6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P'" not in a: raise RuntimeError('Pump original program path was unexpectedly removed')
    if "o.launchPlatforms=['pump','dex'];" not in s: raise RuntimeError('settings did not enable normalized pump+dex routing')
    if 'MEMEFLOW_DEX_CREATOR_NA_WRAPPER_V1_1' not in e: raise RuntimeError('DEX creator N/A wrapper missing')
    for token in ['DEX_STREAM_V1_1','queueDropped','staleDropped','confirmBatches','tokens/v1/solana/']:
        if token not in d: raise RuntimeError('DEX feed hardening validation missing: '+token)

    log('INSTALL COMPLETE')
    log('default source after restart: DEX')
    log('PUMP path preserved and can be restored instantly')
    log('DEX programs: PumpSwap + Raydium CPMM + Raydium CLMM')
    log('DEX pair must be SOL-paired and have real DEX transaction activity before admission')
    log('DEX confirmation is batched; signature queue is bounded and stale work is dropped')
    log('DEX path skips Pump bonding-curve enrichment and Pump price timers')
    log('source control page: /system-source.html')
    log('backup: '+str(BACK))
    log('Restart the Replit workflow/app, then open /system-source.html')
except Exception as e:
    rollback(e)
